-- =============================================================================
-- 0139 · Rutas del bus UDES: la ruta, sus paradas, el trazado por carretera, los
-- estudiantes por celda, los conteos de abordaje y las propuestas de ruta nueva.
--
-- Módulo privado de Planeación (/admin/rutas). Lo que el mapa dibuja sale de aquí:
--
--   bus_routes          una fila por ruta: código, nombre, color, buses, puestos, cada cuántos
--                       minutos sale un bus y cuánto descansa en la UDES.
--   bus_stops           las paradas en orden (seq), con coordenadas y tiempo de parada.
--   bus_route_geometry  el trazado por carretera (lista de [lon, lat]), la distancia,
--                       el tiempo y la distancia de cada tramo entre paradas.
--   bus_origin_cells    estudiantes por celda de ~150 m y periodo. SIEMPRE agregado:
--                       sin direcciones, y una celda con menos de 5 estudiantes no
--                       se guarda (reserva estadística, como en UDES en Cifras).
--   bus_ridership       conteos reales de quienes suben y bajan, por parada y hora.
--   bus_proposals       rutas o paradas propuestas, con su ganancia estimada.
--
-- Quién puede qué: Planeación y la administración leen y escriben; ningún otro rol
-- ni la clave anónima. Mientras bus_origin_cells esté vacía, el mapa usa una muestra
-- ilustrativa y lo dice en pantalla.
--
-- Se siembra la ruta actual (19 paradas, 16,1 km) con el trazado calculado con OSRM
-- sobre calles de OpenStreetMap. Volver a aplicar no pisa lo ya editado.
-- Todo DELETE y UPDATE lleva WHERE (safeupdate, ver 0095). Idempotente.
-- =============================================================================

create table if not exists public.bus_routes (
  id         uuid primary key default gen_random_uuid(),
  code       text not null unique,
  name       text not null,
  color      text not null default '#2166d6',
  vehicles   int  not null default 1,
  capacity   int  not null default 40,
  active     boolean not null default true,
  updated_at timestamptz not null default now(),
  constraint bus_routes_code check (code = btrim(code) and length(code) between 1 and 12),
  constraint bus_routes_name check (length(name) between 1 and 120),
  constraint bus_routes_color check (color ~ '^#[0-9a-fA-F]{6}$'),
  constraint bus_routes_fleet check (vehicles between 1 and 50 and capacity between 5 and 200)
);

-- La flota: cada cuántos minutos sale un bus de la UDES y cuánto descansa allí al llegar.
-- Con `vehicles` buses, la ruta solo cumple el intervalo si un ciclo (recorrido + parada)
-- cabe en vehicles × headway_min; el módulo calcula cuántos buses hacen falta.
alter table public.bus_routes add column if not exists headway_min int not null default 15;
alter table public.bus_routes add column if not exists terminal_dwell_min int not null default 5;
alter table public.bus_routes drop constraint if exists bus_routes_schedule;
alter table public.bus_routes add constraint bus_routes_schedule check (headway_min between 3 and 120 and terminal_dwell_min between 0 and 30);

create table if not exists public.bus_stops (
  id       uuid primary key default gen_random_uuid(),
  route_id uuid not null references public.bus_routes (id) on delete cascade,
  seq      int  not null,
  name     text not null,
  lon      double precision not null,
  lat      double precision not null,
  dwell_s  int  not null default 20,
  unique (route_id, seq),
  constraint bus_stops_name check (length(name) between 1 and 120),
  constraint bus_stops_geo check (lon between -180 and 180 and lat between -90 and 90),
  constraint bus_stops_dwell check (dwell_s between 0 and 300)
);

create table if not exists public.bus_route_geometry (
  route_id        uuid primary key references public.bus_routes (id) on delete cascade,
  coords          jsonb not null,
  distance_m      int   not null,
  duration_s      int   not null,
  leg_distances_m int[] not null,
  engine          text  not null default 'osrm',
  computed_at     timestamptz not null default now(),
  constraint bus_route_geometry_coords check (jsonb_typeof(coords) = 'array' and jsonb_array_length(coords) >= 2)
);

create table if not exists public.bus_origin_cells (
  cell     text not null,
  term     text not null,
  lon      double precision not null,
  lat      double precision not null,
  students int  not null,
  primary key (cell, term),
  constraint bus_origin_cells_reserve check (students >= 5),
  constraint bus_origin_cells_geo check (lon between -180 and 180 and lat between -90 and 90)
);

create table if not exists public.bus_ridership (
  id          uuid primary key default gen_random_uuid(),
  stop_id     uuid not null references public.bus_stops (id) on delete cascade,
  observed_at timestamptz not null,
  boardings   int not null check (boardings >= 0),
  alightings  int not null check (alightings >= 0),
  source      text not null default 'conteo'
);
create index if not exists bus_ridership_stop_time on public.bus_ridership (stop_id, observed_at);

create table if not exists public.bus_proposals (
  id            uuid primary key default gen_random_uuid(),
  route_id      uuid references public.bus_routes (id) on delete set null,
  name          text not null,
  params        jsonb not null default '{}'::jsonb,
  stops         jsonb not null default '[]'::jsonb,
  coverage_gain numeric,
  trips_gain    numeric,
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint bus_proposals_name check (length(name) between 1 and 120)
);

comment on table public.bus_origin_cells is
  'Rutas (0139): estudiantes por celda y periodo. Agregado, mínimo 5 por celda; nunca direcciones.';

-- RLS: Planeación y administración leen y escriben; nadie más.
do $$
declare t text;
begin
  foreach t in array array['bus_routes','bus_stops','bus_route_geometry','bus_origin_cells','bus_ridership','bus_proposals'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_planeacion', t);
    execute format($p$create policy %I on public.%I for all to authenticated using (public.has_role_at_least('planeacion')) with check (public.has_role_at_least('planeacion'))$p$, t || '_planeacion', t);
    execute format('revoke all on public.%I from public, anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;

-- La ruta actual.
insert into public.bus_routes (code, name, color, vehicles, capacity)
values ('R1', 'Campus UDES · Cabecera · Florida', '#2166d6', 3, 70)
on conflict (code) do nothing;

-- Tres buses, uno cada 15 minutos, 5 minutos de parada en la UDES. Si ya se sembró con 2 buses y nadie lo cambió, pasa a 3.
update public.bus_routes set vehicles = 3 where code = 'R1' and vehicles = 2;

